// Deja pasar solo leads con seguimiento vencido HOY y en estado seguible; arma el prompt
const hoy = $now.toFormat('yyyy-LL-dd');
const seguibles = ['borrador_creado','respondio','en_pipeline','nutrir','agendado'];
const out = [];
for (const it of $input.all()) {
  const l = it.json;
  if (!l.Correo || !String(l.Correo).includes('@')) continue;
  if (String(l.Fecha_Siguiente_Paso).slice(0,10) !== hoy) continue;
  if (!seguibles.includes(l.Estado)) continue;
  const system = [
'<identidad>Agente de Seguimiento Comercial B2B de ACCES GROUP. Venta consultiva, sin presion, sin culpa, sin inventar datos.</identidad>',
'<tarea>Redacta un correo de SEGUIMIENTO con valor real. PROHIBIDO: "solo dando seguimiento", "ya revisaste?", "quedo atento" como unico contenido. Cada toque debe aportar 1 de: valor, evidencia, claridad, pregunta util o coordinacion.</tarea>',
'<reglas>Espanol profesional, max ~110 palabras, 1 CTA, sin presion. HTML simple sin firma. Propone nueva fecha_siguiente_paso (~4-6 dias habiles) o cierre de ciclo si ya hubo varios toques sin respuesta.</reglas>',
'<salida>SOLO este JSON sin ``` : {"asunto":"","cuerpo_html":"","fecha_siguiente_paso":"YYYY-MM-DD","razon":""}</salida>'
  ].join('\n');
  const user = `Fecha de hoy: ${hoy}\nLead: ${l.Empresa} — ${l.Contacto} (${l.Cargo})\nEtapa: ${l.Etapa_Pipeline} | Estado: ${l.Estado} | Toques: ${l.Num_Toques}\nUltimo asunto: ${l.Asunto}\nInvestigacion sector: ${l.Investigacion_Sector || ''}\nNotas: ${l.Notas || ''}\n\nRedacta el seguimiento con valor. Devuelve solo el JSON.`;
  out.push({ json: { ...l, system, user, hoy } });
}
return out;

const FIRMA = '<br><br><table cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;font-size:13px;color:#333"><tr><td style="padding-top:12px;border-top:2px solid #0a3d62"><strong style="color:#0a3d62">Nombre Apellido</strong><br><span style="color:#555">Ejecutivo Comercial — ACCES GROUP</span><br><a href="mailto:correo@accesgroup.com" style="color:#0a3d62">correo@accesgroup.com</a></td></tr></table>';
const resp = $json;
let text = '';
try { text = resp.content[0].text; } catch(e) { text = resp.body ? resp.body.content[0].text : '{}'; }
text = text.replace(/^```json/i,'').replace(/```$/,'').trim();
const data = JSON.parse(text);
const lead = $('Filtrar vencidos hoy').item.json;
data.cuerpo_final = (data.cuerpo_html || '') + FIRMA;
return [{ json: { ...lead, ...data } }];
